// jarvisSemantic.js — second-chance matching for the knowledge pack.
//
// The keyword matcher in jarvisKnowledge.js only knows the phrasings someone
// thought to write down. "What stops the loop" misses "stops you from
// looping"; "could it wreck my machine" misses every safety phrase. Each of
// those misses costs the visitor one of three daily live calls on a question
// that was already answered in writing.
//
// So: keyword first (instant, offline, exact), and only on a miss do we spend
// ~200ms embedding the question and comparing it against precomputed vectors
// for the 47 entries. Same shape as the VectorStore in UserSpace.js —
// semantic when it's available, never required for the page to work.
//
// TWO GATES, both measured rather than guessed (see the calibration in
// scripts/embed-jarvis-knowledge.js's sibling experiments):
//
//   1. similarity ≥ THRESHOLD — the question is about this at all
//   2. top-1 must beat top-2 by ≥ TIE_GAP — the match is *decisive*
//
// The second gate is the one doing the real work. An off-topic question
// ("how do i cook pasta") scores mediocre-but-nonzero against everything,
// producing a flat distribution with no clear winner; a genuine paraphrase
// spikes on one entry. Measuring decisiveness catches what an absolute
// threshold alone cannot, and it is also what stops near-ties — two entries
// within 0.003 of each other — from serving a confidently wrong answer.
//
// Failing this check is cheap: the question goes to the live agent, which is
// what would have happened anyway.

import { KNOWLEDGE } from "./jarvisKnowledge";

const VECTORS_URL = `${
  process.env.PUBLIC_URL || ""
}/jarvis/knowledge-vectors.json`;
const EMBED_ENDPOINT =
  "https://us-central1-portfolio-142b7.cloudfunctions.net/embedTexts";

const THRESHOLD = 0.65;
const TIE_GAP = 0.012;
const EMBED_TIMEOUT_MS = 2000;

let indexPromise = null;

function decode(base64, dims) {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
  const view = new DataView(bytes.buffer);
  const out = new Float32Array(dims);
  for (let i = 0; i < dims; i += 1) out[i] = view.getInt16(i * 2, true) / 32767;
  return out;
}

/**
 * Load and decode the precomputed entry vectors. Resolves to [] on any
 * failure — a missing or malformed vectors file degrades this to
 * keyword-only, it never breaks the page.
 */
function loadIndex() {
  if (!indexPromise) {
    indexPromise = fetch(VECTORS_URL)
      .then((response) => (response.ok ? response.json() : null))
      .then((doc) => {
        if (!doc || !Array.isArray(doc.entries) || !doc.dims) return [];
        const byId = new Map(KNOWLEDGE.map((entry) => [entry.id, entry]));
        return (
          doc.entries
            .map((row) => ({
              entry: byId.get(row.id),
              vector: decode(row.v, doc.dims),
            }))
            // An entry deleted from the pack without regenerating vectors would
            // otherwise resolve to undefined and throw at match time.
            .filter((row) => row.entry)
        );
      })
      .catch(() => []);
  }
  return indexPromise;
}

// Called when the composer takes focus: by the time a question is typed the
// 95KB of vectors are usually already here, so a match costs one embed call
// rather than a fetch plus an embed call. Never awaited.
export function warmSemanticIndex() {
  loadIndex();
}

async function embedQuestion(text) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), EMBED_TIMEOUT_MS);
  try {
    const response = await fetch(EMBED_ENDPOINT, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ texts: [text] }),
      signal: controller.signal,
    });
    if (!response.ok) return null;
    const data = await response.json();
    const vector = data && data.vectors && data.vectors[0];
    return Array.isArray(vector) && vector.length ? vector : null;
  } catch {
    // Offline, blocked, rate-limited, or slower than the timeout. Go live.
    return null;
  } finally {
    clearTimeout(timer);
  }
}

/**
 * Returns `{ entry, score, margin }` when the pack decisively covers the
 * question, otherwise null. Never throws.
 */
export async function matchSemantic(question) {
  const text = String(question || "").trim();
  if (text.length < 4) return null;

  const index = await loadIndex();
  if (!index.length) return null;

  const raw = await embedQuestion(text);
  if (!raw) return null;

  // The stored vectors are unit-normalized, so normalizing the query makes
  // the dot product a cosine.
  let sum = 0;
  for (let i = 0; i < raw.length; i += 1) sum += raw[i] * raw[i];
  const length = Math.sqrt(sum) || 1;
  const query = raw.map((value) => value / length);

  if (query.length !== index[0].vector.length) return null;

  let best = { entry: null, score: -1 };
  let second = -1;

  index.forEach(({ entry, vector }) => {
    let score = 0;
    for (let i = 0; i < vector.length; i += 1) score += query[i] * vector[i];
    if (score > best.score) {
      second = best.score;
      best = { entry, score };
    } else if (score > second) {
      second = score;
    }
  });

  if (!best.entry || best.score < THRESHOLD) return null;
  const margin = best.score - second;
  if (margin < TIE_GAP) return null;

  return { entry: best.entry, score: best.score, margin };
}

export default matchSemantic;
