const normalize = (text) =>
  String(text || "")
    .toLowerCase()
    .replace(/[^a-z0-9\s_.-]/g, " ")
    .replace(/\s+/g, " ")
    .trim();

const tokenize = (text) =>
  normalize(text)
    .split(" ")
    .filter((word) => word.length > 2 && !STOPWORDS.has(word));

/**
 * Score a visitor's question against the pack.
 *
 * A phrase hit is worth far more than a token hit: "how many tools" is a
 * question, "tools" on its own is a topic. Requiring at least one phrase hit
 * OR two distinct token hits is what keeps the pack from confidently answering
 * something it was never asked — which would be worse than spending a call.
 *
 * Returns `{ entry, score, confident }` or null.
 */
export function matchKnowledge(question) {
  const text = normalize(question);
  if (text.length < 4) return null;
  // Note: an all-stopword question ("what can you do") tokenizes to nothing,
  // so this must NOT bail early — phrase matching is exactly what carries
  // those, and they are among the most commonly asked.
  const tokens = new Set(tokenize(question));

  let best = null;

  KNOWLEDGE.forEach((entry) => {
    let score = 0;
    let phraseHits = 0;

    entry.phrases.forEach((phrase) => {
      if (text.includes(phrase)) {
        phraseHits += 1;
        // Longer phrases are more specific, so they count for more.
        score += 6 + phrase.split(" ").length;
      }
    });

    let tokenHits = 0;
    entry.keywords.forEach((keyword) => {
      if (tokens.has(keyword)) {
        tokenHits += 1;
        score += 2;
      }
    });

    // The canonical question shares words with the asked one — a weak signal,
    // but it separates near-ties sensibly.
    tokenize(entry.q).forEach((word) => {
      if (tokens.has(word)) score += 0.5;
    });

    if (score > 0 && (!best || score > best.score)) {
      best = { entry, score, phraseHits, tokenHits };
    }
  });

  if (!best) return null;

  const confident = best.phraseHits > 0 || best.tokenHits >= 2;
  if (!confident || best.score < 4) return null;

  return { entry: best.entry, score: best.score, confident };
}

export default KNOWLEDGE;
